-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     sh.SHIPMENT                                     AS \"Receipt No\",     sh.RECEIVE_DATE                                 AS \"Receipt Date\",     sh.INVC_MATCH_STATUS                            AS \"Invoice Match Status\",     CASE sh.INVC_MATCH_STATUS             WHEN 'O'                 THEN 'Open - Awaiting Invoice Match'             WHEN 'C'                 THEN 'Closed'             WHEN 'M'                 THEN 'Matched'             ELSE sh.INVC_MATCH_STATUS     END                                                 AS \"Match Status DESC\",      oh.ORDER_NO                                     AS \"PO Number\",     oh.SUPPLIER                                     AS \"Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     sp.SUP_STATUS                                   AS \"Supplier Status\",     ol.LOCATION                                     AS \"Location ID\",     ol.LOC_TYPE                                     AS \"LOC Type\",     CASE ol.LOC_TYPE             WHEN 'S'                 THEN st.STORE_NAME             WHEN 'W'                 THEN wh.WH_NAME     END                                                 AS \"Location Name\",      ss.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     im.DEPT                                         AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     CASE             WHEN im.DEPT IN (100, 101, 102)                 THEN 'Y'             ELSE 'N'     END                                                 AS \"PACA Eligible IND\",      ss.QTY_RECEIVED                                 AS \"QTY Received\",     ss.UNIT_COST                                    AS \"Unit Cost\",     ROUND(ss.QTY_RECEIVED * ss.UNIT_COST, 2)        AS \"Receipt Cost Value\",     ih.INVC_ID                                      AS \"Invoice ID\",     ih.INVC_DATE                                    AS \"Invoice Date\",     ih.TOTAL_MERCH_COST                             AS \"Invoice Amount\",     sh.RECEIVE_DATE + 10                            AS \"PACA Payment Due Date\",     TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE)         AS \"Days Since Receipt\",     GREATEST( TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) , 0)AS \"Days Past PACA Due Date\",     CASE WHEN TRUNC(SYSDATE) &lt;= TRUNC(sh.RECEIVE_DATE) + 10 THEN 'WITHIN TERMS'             WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) BETWEEN 1 AND 5                 THEN 'PAST DUE - 1-5 DAYS'             WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) BETWEEN 6 AND 15                 THEN 'PAST DUE - 6-15 DAYS'             ELSE 'PAST DUE - 15+ DAYS - TRUST RIGHT RISK'     END                                                 AS \"PACA Compliance Status\",      CASE WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 0 AND 7 THEN '0 - 7 Days'             WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 8 AND 15                 THEN '8 - 15 Days'             WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 16 AND 30                 THEN '16 - 30 Days'             ELSE '30+ Days'     END                                                 AS \"Standard Aging Bucket\",      TRUNC(SYSDATE)                                  AS \"Report Date\"  FROM     MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU         ss   ON  sh.SHIPMENT       = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD         oh   ON  sh.ORDER_NO       = oh.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDLOC          ol   ON  oh.ORDER_NO       = ol.ORDER_NO                                               AND  ss.ITEM            = ol.ITEM                                               AND  sh.TO_LOC          = ol.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  ss.ITEM            = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT            = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_SUPS         sp  ON  oh.SUPPLIER        = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE        st  ON  ol.LOCATION        = st.STORE                                               AND  ol.LOC_TYPE         = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH          wh   ON  ol.LOCATION        = wh.WH                                               AND  ol.LOC_TYPE         = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_INVC_HEAD    ih  ON  oh.SUPPLIER        = ih.SUPPLIER  WHERE     sh.INVC_MATCH_STATUS != 'C'     AND sh.RECEIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)   ORDER BY     CASE         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) &gt; 15              AND im.DEPT IN (100, 101, 102)             THEN 1         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) &gt; 0              AND im.DEPT IN (100, 101, 102)             THEN 2         ELSE 3     END,     sh.RECEIVE_DATE,     sp.SUP_NAME,     sh.SHIPMENT</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Receipt No</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Receipt Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Invoice Match Status</ds:name><ds:datatype>varchar(1)</ds:datatype></ds:column><ds:column><ds:name>Match Status DESC</ds:name><ds:datatype>varchar(29)</ds:datatype></ds:column><ds:column><ds:name>PO Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Supplier ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Supplier Name</ds:name><ds:datatype>varchar(240)</ds:datatype></ds:column><ds:column><ds:name>Supplier Status</ds:name><ds:datatype>varchar(1)</ds:datatype></ds:column><ds:column><ds:name>Location ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOC Type</ds:name><ds:datatype>varchar(1)</ds:d